  as x(content_key text, record_hash text, canonical_record jsonb);

do $$
begin
  if (select count(*) from cleanup_reviewed_vocab_payload) <> 200 then
    raise exception 'catalog_authority_incomplete: expected 200 reviewed records';
  end if;
  if (select count(*) from public.game_words where status = 'active') <> 200 then
    raise exception 'catalog_authority_mismatch: active vocabulary set is not exactly 200';
  end if;
  if exists (
    select 1
    from public.game_words gw
    full join cleanup_reviewed_vocab_payload approved using (content_key)
    where (gw.status = 'active' or gw.content_key is null)
      and (gw.content_key is null or approved.content_key is null)
  ) then
    raise exception 'catalog_authority_mismatch: active vocabulary keys differ';
  end if;
end
$$;

update public.game_words gw
set canonical_record = approved.canonical_record,
    record_hash = approved.record_hash
from cleanup_reviewed_vocab_payload approved
where gw.status = 'active'
  and gw.content_key = approved.content_key
  and not (gw.canonical_record ? 'spellingSyllables');

do $$
begin
  if exists (
    select 1
    from public.game_words gw
    where gw.status = 'active'
      and (
        gw.canonical_record is distinct from (
          select approved.canonical_record
          from cleanup_reviewed_vocab_payload approved
          where approved.content_key = gw.content_key
        )
        or gw.record_hash is distinct from (
          select approved.record_hash
          from cleanup_reviewed_vocab_payload approved
          where approved.content_key = gw.content_key
        )
        or jsonb_typeof(gw.canonical_record -> 'syllables') is distinct from 'array'
        or jsonb_typeof(gw.canonical_record -> 'spellingSyllables') is distinct from 'array'
        or jsonb_array_length(gw.canonical_record -> 'syllables') = 0
        or jsonb_array_length(gw.canonical_record -> 'spellingSyllables')
          <> jsonb_array_length(gw.canonical_record -> 'syllables')
        or (
          select string_agg(part.elem ->> 'th', '' order by part.ord)
          from jsonb_array_elements(gw.canonical_record -> 'spellingSyllables')
            with ordinality as part(elem, ord)
        ) is distinct from (gw.canonical_record ->> 'word')
      )
  ) then
    raise exception 'catalog_authority_incomplete: reviewed canonical record';
  end if;
end
$$;

-- The canonical record is now the only vocabulary authority. Drop every retired
-- parallel answer/segmentation column so no runtime or future writer can use it.
alter table public.game_words
  drop column if exists tone_special,
  drop column if exists tone_override,
  drop column if exists tone_derivation,
  drop column if exists syls,
  drop column if exists read_syls;

commit;
